1	// Dosing helpers for wardline-clinic.
2	
3	export function averageWait(values) {
4	  return values.reduce((a, b) => a + b, 0) / values.length;
5	}
6	
7	export function uniqueBedCodes(codes) {
8	  return [...new Set(codes)];
9	}
10	
11	export function occupancyFraction(pct) {
12	  if (pct < 0 || pct > 100) throw new RangeError("percentage out of range");
13	  return pct / 100;
14	}
15	
16	export function handoverSeconds(minutes) {
17	  return minutes * 60 * 60;
18	}
19

